function updateOneProperty(id,updater,reason='Property update'){const latest=readCanonicalProperties(),previous=properties;const base=latest.find(item=>item.id===id)||properties.find(item=>item.id===id);if(!base)return false;const updated=updater(structuredClone(base));if(!updated||String(updated.id)!==String(id))return false;const next=(latest.length?latest:properties).map(item=>item.id===id?normalizeRecord({...item,...updated},0):item);properties=next;const saved=save({reason});if(saved){renderMarkers();renderList();renderCompare()}else{properties=previous;renderMarkers();renderList();renderCompare()}return saved}
window.OTPropertyStore={
 readSitePlanning(id){const p=(readCanonicalProperties().find(item=>item.id===id)||properties.find(item=>item.id===id));return p?.sitePlanning?structuredClone(p.sitePlanning):null},
 writeSitePlanning(id,sitePlanning,label='Site-planning update'){return updateOneProperty(id,current=>({...current,sitePlanning:structuredClone(sitePlanning),updatedAt:new Date().toISOString(),activityHistory:[...(current.activityHistory||[]),{at:new Date().toISOString(),type:'site-planning',label}]}),label)},
 update(id,updater,reason){return updateOneProperty(id,updater,reason)},
 replaceAll(collection,reason='Bulk property recovery'){const previous=properties;try{properties=collection.map((item,index)=>normalizeRecord(item,index));const saved=save({reason});if(!saved)properties=previous;else{renderMarkers();renderList();renderCompare()}return saved}catch{properties=previous;return false}},
 getProperty(id){const p=(readCanonicalProperties().find(item=>item.id===id)||properties.find(item=>item.id===id));return p?structuredClone(p):null},
 validate(){return validatePropertyCollection(readCanonicalProperties())}
};
function haversineMiles(aLat,aLng,bLat,bLng){const R=3958.8,toRad=v=>v*Math.PI/180,dLat=toRad(bLat-aLat),dLng=toRad(bLng-aLng);const a=Math.sin(dLat/2)**2+Math.cos(toRad(aLat))*Math.cos(toRad(bLat))*Math.sin(dLng/2)**2;return 2*R*Math.asin(Math.sqrt(a))}
function destinationLabel(d){return Array.isArray(d)?d[0]:(d.label||'Destination')}
function destinationTarget(d){if(Array.isArray(d))return d[1];return Number.isFinite(Number(d.lat))&&Number.isFinite(Number(d.lng))?`${d.lat},${d.lng}`:(d.address||d.name||'')}
function routeUrl(p,dest){return `https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(`${p.lat},${p.lng}`)}&destination=${encodeURIComponent(destinationTarget(dest))}`}
function routeCards(p){if(!p.destinations?.length)return '<div class="route-loading">No nearby destinations saved yet.</div>';return p.destinations.map(d=>{const label=destinationLabel(d),name=Array.isArray(d)?d[1]:(d.name||d.address||''),miles=Array.isArray(d)?'':(Number.isFinite(Number(d.distanceMiles))?`${Number(d.distanceMiles).toFixed(1)} mi straight-line`:'');return `<button class="route" onclick="window.open('${routeUrl(p,d)}','_blank')"><b>${escapeHtml(label)}</b>${name?`<span class="route-name">${escapeHtml(name)}</span>`:''}${miles?`<span class="route-distance">${miles}</span>`:''}<span>Open routed directions ↗</span></button>`}).join('')}
