function updateOverallFromManualScores(){const scores=readScoreInputs();document.getElementById('addScore').value=scoreOverall(scores);document.getElementById('baselineMessage').textContent=`Manual category scores set overall to ${scoreOverall(scores)}/100. These values will be saved with the property.`}
function terrainSummary(t){if(!t)return 'Terrain not analyzed. This screening requires a verified pin and does not replace a survey, geotechnical review, or parcel-specific grading plan.';return `USGS terrain screen: ${t.centerElevationFt.toFixed(0)} ft at pin · ${t.reliefFt.toFixed(0)} ft local relief · ${t.avgSlopePct.toFixed(0)}% average sample slope · ${t.maxSlopePct.toFixed(0)}% steepest sample. Buildability screen ${terrainBuildabilityScore(t)}/100.`}
async function analyzeTerrainForProperty(p){const samples=[{lat:p.lat,lng:p.lng,d:0}];for(const bearing of [0,45,90,135,180,225,270,315]){const [lat,lng]=offsetCoordinate(p.lat,p.lng,150,bearing);samples.push({lat,lng,d:150})}for(const x of samples)x.elevationFt=await usgsElevationFeet(x.lat,x.lng);const center=samples[0].elevationFt,slopes=samples.slice(1).map(x=>Math.abs(x.elevationFt-center)/(x.d*3.28084)*100),elev=samples.map(x=>x.elevationFt);p.terrain={source:'USGS 3DEP EPQS',checkedAt:new Date().toISOString(),centerElevationFt:center,reliefFt:Math.max(...elev)-Math.min(...elev),avgSlopePct:slopes.reduce((a,b)=>a+b,0)/slopes.length,maxSlopePct:Math.max(...slopes),sampleCount:samples.length,radiiMeters:[150]}}
window.researchProperty=async function(id){const p=properties.find(x=>x.id===id);if(!p)return;p.researchStatus='Researching…';save();openProperty(id);const before={...(p.scores||{})};const jobs=[window.refreshRoutes(id)];if(!p.terrain)jobs.push(analyzeTerrainForProperty(p));await Promise.allSettled(jobs);const auto=calculateBaselineScores(p);const locks=p.scoreLocks||{};p.scores=Object.fromEntries(Object.keys(auto.scores).map(k=>[k,locks[k]?Number(before[k]??50):Number(auto.scores[k])]));p.score=scoreOverall(p.scores);const changes=Object.keys(p.scores).filter(k=>Number(before[k])!==Number(p.scores[k])).map(k=>`${k} ${before[k]??'—'}→${p.scores[k]}`);if(changes.length)p.scoreAudit=[...(p.scoreAudit||[]),{at:new Date().toISOString(),source:'Property research',changes,overall:p.score}].slice(-25);p.researchStatus='Research updated';p.researchUpdatedAt=new Date().toISOString();p.updatedAt=new Date().toISOString();save();renderList();renderCompare();openProperty(id)}
async function enrichSavedListing(p){
 const listing=canonicalListingInput(p.listing||p.address);const changes=[];
 if(listing.address&&!p.address){p.address=listing.address;changes.push('address from listing URL')}
 if(listing.source&&!p.source){p.source=listing.source;changes.push('source')}
 if(listing.zillowId&&!p.zillowId){p.zillowId=listing.zillowId;changes.push('Zillow property ID')}
 let text='';if(listing.url)text=await fetchListingPage(listing.url);const parsed=parseListingText(text),setIfEmpty=(key,value,label)=>{if(value&&!(Number(p[key])>0)&&!p[key]){p[key]=value;changes.push(label)}};
 setIfEmpty('price',parsed.price,'price');setIfEmpty('acres',parsed.acres,'acreage');setIfEmpty('beds',parsed.beds,'beds');setIfEmpty('baths',parsed.baths,'baths');setIfEmpty('sqft',parsed.sqft,'square feet');setIfEmpty('mls',parsed.mls,'MLS');
 if(text&&!p.notes){const notes=extractListingNotes(text);if(notes){p.notes=notes;changes.push('listing description')}}
  if(!p.points?.reference&&!isUserConfirmedLocation(p)){
   const point=extractListingCoordinates(text);if(point){p.lat=point.lat;p.lng=point.lng;p.points={...(p.points||{}),reference:{lat:point.lat,lng:point.lng}};p.pinQuality=`${point.source} — verify driveway entrance`;p.locationConfidence='review';changes.push('listing coordinates')}
   else if(listing.address){const matches=await window.OTIntegrity?.lookupCandidates?.(listing.address)||[];if(matches[0]){p.lat=matches[0].lat;p.lng=matches[0].lng;p.points={...(p.points||{}),reference:{lat:p.lat,lng:p.lng}};p.pinQuality=matches[0].source;p.locationConfidence='review';changes.push('exact-address coordinates')}}
 }
 return {changes,blocked:!!listing.url&&!text};
}
const researchPropertyCore=window.researchProperty;
window.researchProperty=async function(id){const p=properties.find(x=>x.id===id);if(!p)return;let enrichment={changes:[],blocked:false};try{enrichment=await enrichSavedListing(p)}catch{}if(enrichment.changes.length||enrichment.blocked){p.activityHistory=[...(p.activityHistory||[]),{at:new Date().toISOString(),type:'listing-research',label:enrichment.changes.length?`Research populated: ${enrichment.changes.join(', ')}${enrichment.blocked?' (listing page blocked; URL facts only)':''}`:'Listing page blocked; retained URL-derived address and existing facts.'}];save()}await researchPropertyCore(id)};
function renderTerrainReadout(t=currentTerrainAnalysis){const el=document.getElementById('terrainReadout');if(el)el.textContent=terrainSummary(t)}
function offsetCoordinate(lat,lng,distanceMeters,bearingDeg){const R=6378137,b=bearingDeg*Math.PI/180,p1=lat*Math.PI/180,l1=lng*Math.PI/180,d=distanceMeters/R;const p2=Math.asin(Math.sin(p1)*Math.cos(d)+Math.cos(p1)*Math.sin(d)*Math.cos(b));const l2=l1+Math.atan2(Math.sin(b)*Math.sin(d)*Math.cos(p1),Math.cos(d)-Math.sin(p1)*Math.sin(p2));return [p2*180/Math.PI,l2*180/Math.PI]}
async function usgsElevationFeet(lat,lng){const url=`https://epqs.nationalmap.gov/v1/json?x=${encodeURIComponent(lng)}&y=${encodeURIComponent(lat)}&wkid=4326&units=Feet&includeDate=false`;const r=await fetch(url,{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('USGS elevation service unavailable');const j=await r.json();const value=Number(j.value??j.USGS_Elevation_Point_Query_Service?.Elevation_Query?.Elevation);if(!Number.isFinite(value)||value<-1000)throw new Error('No valid elevation returned');return value}
async function analyzeTerrain(){const pin=document.getElementById('pinReadout'),preferred=window.OTPrecision?.getTerrainPoint?.(),lat=Number(preferred?.lat??pin.dataset.lat),lng=Number(preferred?.lng??pin.dataset.lng),out=document.getElementById('terrainReadout');if(!Number.isFinite(lat)||!Number.isFinite(lng)){out.textContent='Place or verify the property pin before analyzing terrain.';return}out.textContent='Sampling USGS 3DEP elevations around the pin…';document.getElementById('analyzeTerrainBtn').disabled=true;try{const samples=[{lat,lng,d:0}];for(const radius of [75,200])for(const bearing of [0,45,90,135,180,225,270,315]){const [a,o]=offsetCoordinate(lat,lng,radius,bearing);samples.push({lat:a,lng:o,d:radius})}for(const s of samples)s.elevationFt=await usgsElevationFeet(s.lat,s.lng);const center=samples[0].elevationFt,slopes=samples.slice(1).map(s=>Math.abs(s.elevationFt-center)/(s.d*3.28084)*100),elev=samples.map(s=>s.elevationFt);currentTerrainAnalysis={source:'USGS 3DEP EPQS',checkedAt:new Date().toISOString(),centerElevationFt:center,reliefFt:Math.max(...elev)-Math.min(...elev),avgSlopePct:slopes.reduce((a,b)=>a+b,0)/slopes.length,maxSlopePct:Math.max(...slopes),sampleCount:samples.length,radiiMeters:[75,200]};renderTerrainReadout();recalculateBaseline()}catch(err){out.textContent=`Terrain analysis could not complete: ${err.message}. You can still score buildability manually.`}finally{document.getElementById('analyzeTerrainBtn').disabled=false}}
