window.setAddPin=function setAddPin(lat,lng,quality='Manually placed pin'){
  const ll=[Number(lat),Number(lng)];
  if(!Number.isFinite(ll[0])||!Number.isFinite(ll[1])||Math.abs(ll[0])<0.0001&&Math.abs(ll[1])<0.0001||ll[0]<18||ll[0]>72||ll[1]<-180||ll[1]>-66){
    const msg=document.getElementById('addMessage');if(msg)msg.textContent='Invalid or non-U.S. coordinates were rejected. No pin was placed.';return false
  }
  if(addPin)map.removeLayer(addPin);
  addPin=L.marker(ll,{draggable:true}).addTo(map).bindTooltip('New property pin',{permanent:false});
 addPin.on('dragend',()=>{const p=addPin.getLatLng();updatePinReadout(p.lat,p.lng,'Manually adjusted pin');window.OTIntegrity?.setManualLocation(p.lat,p.lng,'Manual marker adjustment');recalculateBaseline()});
  updatePinReadout(ll[0],ll[1],quality);
  map.setView(ll,15,{animate:false});
  recalculateBaseline();
  return true;
}
