function readParcelInputs(){return normalizeParcel({county:document.getElementById('parcelCounty')?.value,state:document.getElementById('parcelState')?.value,parcelId:document.getElementById('parcelId')?.value,source:document.getElementById('parcelSource')?.value,checkedAt:document.getElementById('parcelCheckedAt')?.value,gisUrl:document.getElementById('parcelGisUrl')?.value,recordUrl:document.getElementById('parcelRecordUrl')?.value,notes:document.getElementById('parcelNotes')?.value})}
function writeParcelInputs(value={}){const parcel=normalizeParcel(value),fields={parcelCounty:parcel.county,parcelState:parcel.state||'TN',parcelId:parcel.parcelId,parcelSource:parcel.source,parcelCheckedAt:parcel.checkedAt,parcelGisUrl:parcel.gisUrl,parcelRecordUrl:parcel.recordUrl,parcelNotes:parcel.notes};Object.entries(fields).forEach(([id,current])=>{const el=document.getElementById(id);if(el)el.value=current||''});renderParcelGeometryStatus()}
function readParcelGeometryInput(){const input=document.getElementById('parcelGeometryInput')?.value.trim();if(!input)return undefined;let parsed;try{parsed=JSON.parse(input)}catch{throw new Error('Parcel geometry must be valid GeoJSON JSON.')};const geometry=normalizeParcelGeometry(parsed);if(!geometry)throw new Error('Parcel geometry must be a U.S. GeoJSON Polygon or MultiPolygon.');return geometry}
function writeParcelGeometryInput(value){const el=document.getElementById('parcelGeometryInput');if(el)el.value=value?JSON.stringify(value):'';renderParcelGeometryStatus()}
function renderParcelGeometryStatus(){const status=document.getElementById('parcelGeometryStatus'),input=document.getElementById('parcelGeometryInput')?.value.trim();if(!status)return;if(!input){status.textContent='No verified parcel geometry stored. The address pin remains separate.';return}try{status.textContent=normalizeParcelGeometry(JSON.parse(input))?'Verified GeoJSON geometry will be stored separately from the address pin.':'Geometry is not a valid U.S. Polygon or MultiPolygon.'}catch{status.textContent='Geometry is not valid JSON.'}}
function readPhotoInputs(){return normalizePhotos({primary:document.getElementById('primaryPhotoUrl')?.value,additional:linesToArray(document.getElementById('additionalPhotoUrls')?.value||'')})}
function writePhotoInputs(value={}){const photos=normalizePhotos(value),primary=document.getElementById('primaryPhotoUrl'),additional=document.getElementById('additionalPhotoUrls');if(primary)primary.value=photos.primary||'';if(additional)additional.value=(photos.additional||[]).join('\n');renderPhotoFormPreview()}
function renderPhotoFormPreview(){const box=document.getElementById('photoFormPreview'),photos=readPhotoInputs();if(!box)return;if(!photos.primary){box.hidden=true;box.innerHTML='';return}box.hidden=false;box.innerHTML=`<img src="${escapeHtml(photos.primary)}" alt="Primary property preview" referrerpolicy="no-referrer"><span>Preview only — confirm the image belongs to this property.</span>`}
function applyLocationToProperty(p,candidate={}){if(!p||!validUsCoordinate(candidate.lat,candidate.lng)||!canApplyLocation(p,candidate))return false;p.lat=Number(candidate.lat);p.lng=Number(candidate.lng);p.points={...(p.points||{}),reference:{lat:p.lat,lng:p.lng}};p.pinQuality=String(candidate.pinQuality||candidate.source||'Located property pin');p.locationConfidence=String(candidate.status||candidate.confidence||'review');p.locationVerification={status:p.locationConfidence,source:String(candidate.source||p.pinQuality),userVerified:false,checkedAt:new Date().toISOString(),lat:p.lat,lng:p.lng};p.locationAudit=[...(p.locationAudit||[]),{at:new Date().toISOString(),action:'Research location applied',source:p.locationVerification.source,lat:p.lat,lng:p.lng,accepted:true}];return true}
function fillPropertyForm(p){
 editingPropertyId=p.id;window.OT_IMPORTED_INFRASTRUCTURE={...(p.infrastructure||{})};openAddView();document.getElementById('formTitle').textContent=`Edit ${p.id}`;document.getElementById('savePropertyBtn').textContent='Update property';
 const values={addListing:p.listing,addAddress:cleanImportedAddress(p.address),addName:preferredPropertyTitle(p.name,p.address),addPrice:p.price,addAcres:p.acres,addScore:p.score,addMls:p.mls,addBeds:p.beds,addBaths:p.baths,addSqft:p.sqft,addSource:p.source,addNotes:p.notes,addPros:(p.pros||[]).join('\n'),addCons:(p.cons||[]).join('\n')};
  Object.entries(values).forEach(([id,value])=>{const el=document.getElementById(id);if(el)el.value=value??''});writeParcelInputs(p.parcel);writeParcelGeometryInput(p.parcelGeometry);writePhotoInputs(p.photos);
 document.getElementById('addStatus').value=p.status;document.getElementById('addVisitStatus').value=p.visitStatus||'Not visited';document.getElementById('addPropertyType').value=canonicalPropertyType(p.propertyType,p.beds,p.sqft);document.getElementById('addWaterFeature').value=p.waterFeature||'Unknown';writeInvestmentInputs(p.investment);writeDevelopmentInputs(p.development||{});
 currentTerrainAnalysis=p.terrain||null;renderTerrainReadout();writeScoreInputs(p.scores);setAddPin(p.lat,p.lng,p.pinQuality||'Current pin');if(window.OTPrecision)window.OTPrecision.loadProperty(p);if(window.OTIntegrity)window.OTIntegrity.loadProperty(p);document.getElementById('addScore').value=p.score;document.getElementById('baselineMessage').textContent='Editing saved scores. Manual category changes update the overall score and will save.'
}
window.editProperty=function(id){const p=properties.find(x=>x.id===id);if(!p)return;closeDrawer();fillPropertyForm(p)}
async function geocodeAddress(){
  if(window.OTIntegrity?.geocodeAddress)return window.OTIntegrity.geocodeAddress();
  const address=document.getElementById('addAddress').value.trim(),msg=document.getElementById('addMessage');
  if(!address){msg.textContent='Enter the full property address first.';return false}
  msg.textContent='Precision address lookup is still loading. Try Find address again.';
  return false
}

function beginDropPin(){addPinMode=true;openAddView();document.querySelector('[data-view="mapView"]').click();document.body.classList.add('pin-mode');document.querySelector('.map-status').classList.add('pin-instruction');document.querySelector('.map-status').innerHTML='<span>Tap the driveway or property entrance</span><button type="button" onclick="cancelDropPin()">Cancel</button>'}
window.cancelDropPin=function(){addPinMode=false;document.body.classList.remove('pin-mode');document.querySelector('.map-status').classList.remove('pin-instruction');document.querySelector('.map-status').innerHTML=`<span id="pinCount">${properties.length} property pins</span><button onclick="fitProperties()">Show all</button>`}
map.on('click',e=>{if(addPinMode){setAddPin(e.latlng.lat,e.latlng.lng,'Dropped on map');window.OTIntegrity?.setManualLocation(e.latlng.lat,e.latlng.lng,'Manual map placement');cancelDropPin();openAddView();return}if(editPinState){const m=markers[editPinState.id];m.setLatLng(e.latlng);editPinState.pending=e.latlng;showPinEditBar(editPinState.id)}})
window.startPinEdit=function(id){const p=properties.find(x=>x.id===id);if(!p)return;closeDrawer();document.querySelector('[data-view="mapView"]').click();editPinState={id,original:L.latLng(p.lat,p.lng),pending:L.latLng(p.lat,p.lng)};markers[id].dragging.enable();markers[id].on('dragend',pinDragEnd);document.body.classList.add('pin-mode');showPinEditBar(id);map.setView([p.lat,p.lng],16,{animate:false})}
function pinDragEnd(e){if(!editPinState)return;editPinState.pending=e.target.getLatLng();showPinEditBar(editPinState.id)}
function showPinEditBar(id){const p=properties.find(x=>x.id===id),ll=editPinState.pending;document.querySelector('.map-status').classList.add('pin-instruction');document.querySelector('.map-status').innerHTML=`<span>Move ${p.name} pin: ${ll.lat.toFixed(6)}, ${ll.lng.toFixed(6)}</span><button type="button" onclick="savePinEdit()">Save</button><button type="button" onclick="cancelPinEdit()">Cancel</button>`}
window.savePinEdit=function(){if(!editPinState)return;const p=properties.find(x=>x.id===editPinState.id),ll=editPinState.pending;snapshot();p.lat=ll.lat;p.lng=ll.lng;p.pinQuality='Manually verified pin';p.locationConfidence='verified';p.points={...(p.points||{}),reference:{lat:ll.lat,lng:ll.lng}};p.locationAudit=[...(p.locationAudit||[]),{source:'manual-map-adjustment',lat:ll.lat,lng:ll.lng,at:new Date().toISOString(),accepted:true}];p.locationVerification={status:'verified',source:'Manual satellite/map adjustment',verifiedAt:new Date().toISOString(),lat:ll.lat,lng:ll.lng};p.activityHistory=[...(p.activityHistory||[]),{at:new Date().toISOString(),type:'pin-verified',label:'Property reference pin manually verified'}];markers[p.id].dragging.disable();markers[p.id].off('dragend',pinDragEnd);save();finishPinEdit();renderList();openProperty(p.id)}
window.cancelPinEdit=function(){if(!editPinState)return;const m=markers[editPinState.id];m.setLatLng(editPinState.original);m.dragging.disable();m.off('dragend',pinDragEnd);finishPinEdit()}
function finishPinEdit(){editPinState=null;document.body.classList.remove('pin-mode');document.querySelector('.map-status').classList.remove('pin-instruction');document.querySelector('.map-status').innerHTML=`<span id="pinCount">${properties.length} property pins</span><button onclick="fitProperties()">Show all</button>`}

function undoLastChange(){try{const old=JSON.parse(localStorage.getItem(BACKUP_KEY)||'null');if(!Array.isArray(old)||!old.length){setDataMessage('No recovery copy is available yet.');return}const current=properties;createRecoverySnapshot('Before undoing last change');properties=old.map(normalizeRecord);const restoredSeedIds=new Set(properties.filter(p=>seed.some(s=>String(s.id)===String(p.id))).map(p=>String(p.id)));saveDeletedPropertyIds(deletedPropertyIds().filter(id=>!restoredSeedIds.has(String(id))));localStorage.setItem(BACKUP_KEY,JSON.stringify(current));reconcileScoutPins();save();renderMarkers();renderScoutPins();renderList();renderCompare();fitProperties();setDataMessage('Last property change was undone. Any restored seed-property tombstones were cleared.')}catch{setDataMessage('The recovery copy could not be restored.')}}
function reconcileScoutPins(){const ids=new Set(properties.map(p=>String(p.id)));scoutPins=scoutPins.filter(pin=>!pin.propertyId||ids.has(String(pin.propertyId)));saveScoutPins()}
function restoreSeedData(){
 if(!confirm('Restore all original Operation Turtle properties? Your current records are protected in a recovery snapshot, and user-created properties will remain.'))return;
 const priorProperties=properties,priorPins=scoutPins,priorTombstones=deletedPropertyIds();snapshot('Before restoring original seed properties');
 const seedIds=new Set(seed.map(p=>String(p.id)));
 const userCreated=properties.filter(p=>!seedIds.has(String(p.id)));
 properties=[...structuredClone(seed),...userCreated];
 saveDeletedPropertyIds(priorTombstones.filter(id=>!seedIds.has(String(id))));
 reconcileScoutPins();if(!save({reason:'Restore original seed properties'})){properties=priorProperties;scoutPins=priorPins;saveDeletedPropertyIds(priorTombstones);saveScoutPins();renderMarkers();renderScoutPins();renderList();renderCompare();setDataMessage('Original properties could not be restored. Your current data was left unchanged.');return}renderMarkers();renderScoutPins();renderList();renderCompare();fitProperties();showStorageHostWarning();setDataMessage('Original properties restored. User-created properties were retained and seed deletion tombstones were cleared.');
}
let deletionInProgress=false,lastDeletedPropertyState=null,deleteUndoTimer=null;
function renderAfterPropertyDeletion(){renderMarkers();renderScoutPins();renderList();renderCompare();fitProperties()}
function showDeletionUndo(label){const message=document.getElementById('dataMessage');if(!message)return;clearTimeout(deleteUndoTimer);message.innerHTML=`${escapeHtml(label)} deleted. <button id="undoDeletedPropertyBtn" class="secondary outline" type="button">Undo</button>`;document.getElementById('undoDeletedPropertyBtn')?.addEventListener('click',()=>window.undoDeletedProperty?.());deleteUndoTimer=setTimeout(()=>{if(lastDeletedPropertyState){lastDeletedPropertyState=null;setDataMessage(`${label} deleted. Recovery snapshots retain the prior state.`)}},12000)}
window.undoDeletedProperty=function(){const deleted=lastDeletedPropertyState;if(!deleted||deletionInProgress)return;deletionInProgress=true;try{if(properties.some(property=>String(property.id)===String(deleted.property.id))){setDataMessage('That property is already present.');return}const priorProperties=properties,priorPins=scoutPins,priorTombstones=deletedPropertyIds();properties=[...properties,structuredClone(deleted.property)];scoutPins=[...scoutPins.filter(pin=>String(pin.propertyId||'')!==String(deleted.property.id)),...structuredClone(deleted.scoutPins)];saveDeletedPropertyIds(deleted.tombstones);saveScoutPins();if(!save({reason:'Undo property deletion'})){properties=priorProperties;scoutPins=priorPins;saveDeletedPropertyIds(priorTombstones);saveScoutPins();renderAfterPropertyDeletion();setDataMessage('Undo could not be saved. The deleted property remains protected in recovery snapshots.');return}renderAfterPropertyDeletion();lastDeletedPropertyState=null;clearTimeout(deleteUndoTimer);setDataMessage(`${preferredPropertyTitle(deleted.property.name,deleted.property.address)} restored.`)}finally{deletionInProgress=false}}
window.deleteProperty=function(id){if(deletionInProgress)return;const p=properties.find(x=>x.id===id);if(!p)return;const label=preferredPropertyTitle(p.name,p.address);if(!confirm(`Delete ${label}?\n\nThis removes the property, its Site Planning concepts and drawings, cached route profiles, and attached map pins from this device. A recovery snapshot is created first.`))return;deletionInProgress=true;try{const priorProperties=properties,priorPins=scoutPins,priorTombstones=deletedPropertyIds(),removedPins=scoutPins.filter(pin=>String(pin.propertyId||'')===String(id));snapshot('Before deleting property');properties=properties.filter(x=>x.id!==id);if(seed.some(x=>String(x.id)===String(id)))saveDeletedPropertyIds([...priorTombstones,String(id)]);scoutPins=scoutPins.filter(pin=>String(pin.propertyId||'')!==String(id));saveScoutPins();if(!save({reason:'Delete property'})){properties=priorProperties;scoutPins=priorPins;saveDeletedPropertyIds(priorTombstones);saveScoutPins();renderAfterPropertyDeletion();setDataMessage(`Could not delete ${label}. Your property data was left unchanged.`);return}if(editPinState?.id===id)finishPinEdit();window.OTPlanning?.closeForProperty?.(id);closeDrawer();renderAfterPropertyDeletion();lastDeletedPropertyState={property:structuredClone(p),scoutPins:structuredClone(removedPins),tombstones:priorTombstones};showDeletionUndo(label)}finally{deletionInProgress=false}}
function renderRecoverySnapshots(){const panel=document.getElementById('recoverySnapshotsPanel');if(!panel)return;const entries=recoverySnapshots();panel.innerHTML=entries.length?entries.map(entry=>`<div class="recovery-snapshot"><div><b>${escapeHtml(entry.reason||'Recovery snapshot')}</b><span>${new Date(entry.createdAt).toLocaleString()}</span></div><button class="secondary outline" type="button" onclick="restoreRecoverySnapshot('${entry.id}')">Restore</button></div>`).join(''):'<div class="recovery-empty">No recovery snapshots are available yet.</div>'}
window.restoreRecoverySnapshot=function(id){const entry=recoverySnapshots().find(x=>x.id===id);if(!entry||!entry.state)return;if(!confirm(`Restore the snapshot from ${new Date(entry.createdAt).toLocaleString()}? Current data will first be protected in a new recovery snapshot.`))return;createRecoverySnapshot('Before restoring recovery snapshot');for(const key of OT_STATE_KEYS){const value=Object.prototype.hasOwnProperty.call(entry.state,key)?entry.state[key]:null;if(value===null)localStorage.removeItem(key);else localStorage.setItem(key,value)}location.reload()}
function operationTurtleStorageState(){return Object.fromEntries(Object.keys(localStorage).filter(key=>key.startsWith('ot-')).map(key=>[key,localStorage.getItem(key)]))}
window.exportData=function(){const payload={app:'Operation Turtle',backupFormat:'complete-state-v1',version:localStorage.getItem('ot-version')||SEED_VERSION,exportedAt:new Date().toISOString(),state:operationTurtleStorageState()};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download=`operation-turtle-complete-backup-${payload.exportedAt.slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function validateImportedProperties(value){if(!Array.isArray(value))throw new Error('The backup does not contain a property array.');const normalized=value.map(normalizeRecord),ids=new Set();normalized.forEach(p=>{if(ids.has(p.id))throw new Error(`Duplicate property ID: ${p.id}`);ids.add(p.id)});return normalized}
function validateCompleteBackup(payload){if(payload?.app!=='Operation Turtle'||payload?.backupFormat!=='complete-state-v1'||!payload.state||typeof payload.state!=='object'||Array.isArray(payload.state))throw new Error('This is not a complete Operation Turtle backup.');for(const [key,value] of Object.entries(payload.state))if(!key.startsWith('ot-')||typeof value!=='string')throw new Error(`Invalid backup state entry: ${key}`);if(!(STORAGE_KEY in payload.state))throw new Error('The backup is missing ot-properties.');const normalized=validateImportedProperties(JSON.parse(payload.state[STORAGE_KEY]));if(payload.state[SCOUT_PIN_KEY]!==undefined&&!Array.isArray(JSON.parse(payload.state[SCOUT_PIN_KEY])))throw new Error('The backup contains invalid scout pins.');return {state:payload.state,propertyCount:normalized.length}}
function replaceOperationTurtleState(state){const currentRecovery=localStorage.getItem(RECOVERY_SNAPSHOTS_KEY);Object.keys(localStorage).filter(key=>key.startsWith('ot-')&&key!==RECOVERY_SNAPSHOTS_KEY).forEach(key=>localStorage.removeItem(key));Object.entries(state).filter(([key])=>key!==RECOVERY_SNAPSHOTS_KEY).forEach(([key,value])=>localStorage.setItem(key,value));let combined=[];try{combined=[...JSON.parse(currentRecovery||'[]'),...JSON.parse(state[RECOVERY_SNAPSHOTS_KEY]||'[]')].slice(0,RECOVERY_SNAPSHOT_LIMIT)}catch{combined=JSON.parse(currentRecovery||'[]')}localStorage.setItem(RECOVERY_SNAPSHOTS_KEY,JSON.stringify(combined))}
async function importBackupFile(file){const parsed=JSON.parse(await file.text());if(parsed?.backupFormat==='complete-state-v1'){const checked=validateCompleteBackup(parsed);if(!confirm(`Import complete backup from ${new Date(parsed.exportedAt||Date.now()).toLocaleString()}? It contains ${checked.propertyCount} properties and will replace current Operation Turtle data after a recovery snapshot is created.`))return;snapshot('Before importing complete backup');replaceOperationTurtleState(checked.state);location.reload();return}const arr=Array.isArray(parsed)?parsed:parsed?.properties;const normalized=validateImportedProperties(arr);if(!confirm(`Import legacy backup with ${normalized.length} properties? Current properties will first be protected in a recovery snapshot.`))return;snapshot('Before importing legacy backup');properties=normalized;if(Array.isArray(parsed?.scoutPins)){scoutPins=parsed.scoutPins.map(normalizeScoutPin);saveScoutPins()}save();renderMarkers();renderScoutPins();renderList();renderCompare();fitProperties();setDataMessage(`${properties.length} properties imported successfully.`)}
function openSettings(){const panel=document.getElementById('settingsPanel');panel.hidden=false;document.getElementById('versionInfo').textContent=`Operation Turtle ${localStorage.getItem('ot-version')||SEED_VERSION} · Complete backup format v1`;}
function closeSettings(){document.getElementById('settingsPanel').hidden=true}
document.getElementById('settingsBtn').addEventListener('click',openSettings);document.getElementById('closeSettingsBtn').addEventListener('click',closeSettings);document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!document.getElementById('settingsPanel')?.hidden){event.preventDefault();closeSettings();document.getElementById('settingsBtn')?.focus()}});document.getElementById('exportSettingsBtn').addEventListener('click',window.exportData);
