document.getElementById('analyzeListingBtn').addEventListener('click',analyzeListing);document.getElementById('clearImportBtn').addEventListener('click',clearListingImport);document.getElementById('findAddressBtn').addEventListener('click',geocodeAddress);document.getElementById('recalcScoreBtn').addEventListener('click',recalculateBaseline);document.getElementById('analyzeTerrainBtn').addEventListener('click',analyzeTerrain);
['scorePrivacy','scoreInfrastructure','scoreBuildability','scoreShopping','scoreAirport','scoreRecreation','scoreValue','scoreInvestmentFlexibility'].forEach(id=>document.getElementById(id).addEventListener('input',updateOverallFromManualScores));
