document.getElementById('useMapCenterBtn').addEventListener('click',()=>{const center=map.getCenter();window.setAddPin(center.lat,center.lng,'Map center — review recommended');window.OTIntegrity?.setManualLocation(center.lat,center.lng,'Map center selected by user');document.getElementById('locationConfidence').value='review';document.getElementById('locationMessage').textContent=`Map-center pin: ${center.lat.toFixed(6)}, ${center.lng.toFixed(6)}. Adjust it if needed before saving.`});
document.getElementById('openListingMapBtn').addEventListener('click',()=>{const url=document.getElementById('addListing').value.trim();if(!url){document.getElementById('addMessage').textContent='Add a listing URL first, then Open listing map.';return}window.open(url,'_blank','noopener')});
