const SEARCH_HISTORY_KEY='ot-map-search-history';
function searchCenter(){const openId=document.querySelector('#drawer .prop-id')?.textContent?.trim();const p=properties.find(x=>x.id===openId);return p?L.latLng(p.lat,p.lng):map.getCenter()}
