function canonicalPropertyType(value='',beds=0,sqft=0){const v=String(value||'');if(['existing-livable-home','existing-home-renovation','cabin-secondary-dwelling','structure-with-utilities','improved-land-utilities','raw-land'].includes(v))return v;if(/home with acreage|improved property/i.test(v)||(Number(beds)||Number(sqft)))return 'existing-livable-home';if(/improved land/i.test(v))return 'improved-land-utilities';return 'raw-land'}
function defaultInvestment(){return {dwellingCondition:'unknown',utilities:'unknown',rentalPotential:'unknown',subdivisionPotential:'unknown',occupyDuringBuild:'unknown'}}
function readInvestmentInputs(){return {dwellingCondition:document.getElementById('investmentDwellingCondition')?.value||'unknown',utilities:document.getElementById('investmentUtilities')?.value||'unknown',rentalPotential:document.getElementById('investmentRentalPotential')?.value||'unknown',subdivisionPotential:document.getElementById('investmentSubdivisionPotential')?.value||'unknown',occupyDuringBuild:document.getElementById('investmentOccupyDuringBuild')?.value||'unknown'}}
