function investmentFlexibilityScore(propertyType,income={}){const v={...defaultInvestment(),...(income||{})},type=canonicalPropertyType(propertyType);let score=50;score+=({"existing-livable-home":12,"existing-home-renovation":5,"cabin-secondary-dwelling":8,"structure-with-utilities":4,"improved-land-utilities":3,"raw-land":0}[type]||0);score+=({"livable-ready":13,"livable-minor":8,"needs-renovation":-3,unknown:0}[v.dwellingCondition]||0);score+=({"fully-onsite":8,"partial-onsite":4,"at-road":2,"none-verified":0,unknown:0}[v.utilities]||0);score+=({established:7,likely:5,possible:2,none:0,unknown:0}[v.rentalPotential]||0);score+=({strong:6,possible:3,unlikely:0,unknown:0}[v.subdivisionPotential]||0);score+=({yes:6,limited:3,no:0,unknown:0}[v.occupyDuringBuild]||0);return clampScore(score)}
function defaultScores(score){score=clampScore(score||50);return {...Object.fromEntries(Object.keys(SCORE_WEIGHTS).filter(key=>key!=='InvestmentFlexibility').map(key=>[key,score])),InvestmentFlexibility:50}}
