function readScoreInputs(){return {Privacy:clampScore(document.getElementById('scorePrivacy').value),Infrastructure:clampScore(document.getElementById('scoreInfrastructure').value),Buildability:clampScore(document.getElementById('scoreBuildability').value),Shopping:clampScore(document.getElementById('scoreShopping').value),Airport:clampScore(document.getElementById('scoreAirport').value),Recreation:clampScore(document.getElementById('scoreRecreation').value),Value:clampScore(document.getElementById('scoreValue').value),InvestmentFlexibility:clampScore(document.getElementById('scoreInvestmentFlexibility').value)}}
