function recalculateBaseline(){const pin=document.getElementById('pinReadout'),result=calculateBaselineScores({acres:document.getElementById('addAcres').value,price:document.getElementById('addPrice').value,beds:document.getElementById('addBeds').value,sqft:document.getElementById('addSqft').value,lat:pin.dataset.lat,lng:pin.dataset.lng,propertyType:document.getElementById('addPropertyType')?.value||'raw-land',investment:readInvestmentInputs(),development:readDevelopmentInputs(),terrain:currentTerrainAnalysis,infrastructure:window.OT_IMPORTED_INFRASTRUCTURE||{},developmentCost:window.OTPrecision?.readCostInputs?.()||{}});result.scores=window.OTIntegrity?.applyScoreLocks?.(result.scores,readScoreInputs())||result.scores;result.overall=scoreOverall(result.scores);writeScoreInputs(result.scores);document.getElementById('addScore').value=result.overall;const parts=[];if(Number.isFinite(result.airportMiles))parts.push(`nearest major airport ≈ ${result.airportMiles.toFixed(0)} straight-line mi`);if(Number.isFinite(result.serviceMiles))parts.push(`service center ≈ ${result.serviceMiles.toFixed(0)} mi`);parts.push(`investment & flexibility ${result.scores.InvestmentFlexibility}`);document.getElementById('baselineMessage').textContent=`Baseline ${result.overall}/100${parts.length?' · '+parts.join(' · '):''}. Existing-use flexibility is weighted at 15%.`;return result}
window.OTScoring={weights:SCORE_WEIGHTS,runRegressionChecks(){const sum=Object.values(SCORE_WEIGHTS).reduce((a,b)=>a+b,0),existing=normalizeRecord(seed[0]),base={acres:30,price:300000,lat:35.4,lng:-84.3,development:{driveway:'existing',homesite:'identified',utilities:'onsite'},infrastructure:{},developmentCost:{well:false,septic:false}},raw=calculateBaselineScores({...base,propertyType:'raw-land',investment:defaultInvestment()}),home=calculateBaselineScores({...base,propertyType:'existing-livable-home',investment:{dwellingCondition:'livable-ready',utilities:'fully-onsite',rentalPotential:'likely',subdivisionPotential:'possible',occupyDuringBuild:'yes'}}),exceptionalRaw=scoreOverall({Privacy:95,Infrastructure:95,Buildability:95,Shopping:95,Airport:95,Recreation:95,Value:95,InvestmentFlexibility:50}),bounded=[...Object.values(home.scores),home.overall,raw.overall,exceptionalRaw].every(value=>value>=0&&value<=100);return {passed:sum===100&&!!existing&&home.overall>raw.overall&&exceptionalRaw>=85&&bounded,checks:{weightsTotal100:sum===100,existingRecordsLoad:!!existing,usableHomeOutranksComparableRaw:home.overall>raw.overall,exceptionalRawCanScoreHigh:exceptionalRaw>=85,scoresBounded:bounded},sample:{raw:raw.overall,home:home.overall,exceptionalRaw}}}};
function organizeDossier(id){const p=properties.find(item=>item.id===id),body=document.querySelector('#drawer .drawer-body');if(!p||!body||body.querySelector('.dossier-tabs'))return;const nav=document.createElement('div'),panels=document.createElement('div'),tabs=['Overview','Land & Home','Access & Destinations','Investment','Research Sources','History'];nav.className='dossier-tabs';panels.className='dossier-tab-panels';const groups=Object.fromEntries(tabs.map(tab=>[tab,document.createElement('div')]));Object.entries(groups).forEach(([tab,panel])=>{panel.className='dossier-tab-panel';panel.dataset.dossierTab=tab;panel.hidden=tab!=='Overview';panels.appendChild(panel);const button=document.createElement('button');button.type='button';button.textContent=tab;button.className=tab==='Overview'?'active':'';button.addEventListener('click',()=>{nav.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===button));Object.entries(groups).forEach(([name,value])=>value.hidden=name!==tab)});nav.appendChild(button)});const children=[...body.children];children.forEach(child=>{const text=child.textContent||'';let target='Overview';if(/Research history|Score history/i.test(text))target='History';else if(/Route launchpad|Destination|airport/i.test(text))target='Access & Destinations';else if(/Development readiness|Site-development|Precision locations|Land-intelligence/i.test(text))target='Land & Home';else if(/Investment|Why it scores/i.test(text))target='Investment';groups[target].appendChild(child)});const sources=document.createElement('div');sources.className='section';sources.innerHTML=`<h3>Source status</h3><div class="small">Address: ${p.points?.reference?'located':'needs review'} · Listing: ${p.listing?'URL saved':'not supplied'} · County assessor/GIS: not connected · Fields requiring review: ${(p.locationConfidence==='verified'?'none':'pin confirmation')}</div>`;groups['Research Sources'].appendChild(sources);body.prepend(panels);body.prepend(nav)}
function locationStatusLabel(p){if(isUserConfirmedLocation(p))return 'User-confirmed location';if(p.locationConfidence==='high')return 'High-confidence address location';if(p.locationConfidence==='review')return 'Approximate location — review needed';return 'Location needs verification'}
function appendDossierPropertySummary(id){const p=properties.find(item=>item.id===id),overview=document.querySelector('#drawer [data-dossier-tab="Overview"]');if(!p||!overview||overview.querySelector('[data-property-visual]'))return;const parcel=normalizeParcel(p.parcel),photos=normalizePhotos(p.photos),hasBoundary=!!normalizeParcelGeometry(p.parcelGeometry)||(Array.isArray(p.boundary)&&p.boundary.length>=3),card=document.createElement('section');card.className='property-visual-summary';card.dataset.propertyVisual='true';const photo=photos.primary?`<img src="${escapeHtml(photos.primary)}" alt="${escapeHtml(preferredPropertyTitle(p.name,p.address))}" referrerpolicy="no-referrer">`:'<div class="property-photo-placeholder">No property photo saved</div>';card.innerHTML=`<div class="property-photo">${photo}</div><div class="property-visual-copy"><div class="property-visual-address">${escapeHtml(p.address)}</div><div class="property-visual-facts">${p.price?money(p.price):'Price not entered'}${p.acres?` · ${p.acres} ac`:''}${p.price&&p.acres?` · ${money(p.price/p.acres)}/ac`:''}</div><span class="confidence-pill ${escapeHtml(p.locationConfidence||'needs-pin')}">${escapeHtml(locationStatusLabel(p))}</span><div class="small">Parcel: ${parcel.parcelId?escapeHtml(parcel.parcelId):'not recorded'}${parcel.county?` · ${escapeHtml(parcel.county)} County${parcel.state?`, ${escapeHtml(parcel.state)}`:''}`:''}</div><div class="dossier-tools"><button class="secondary outline" type="button" onclick="startPinEdit('${escapeHtml(p.id)}')">Adjust property location</button>${hasBoundary?`<button class="secondary outline" type="button" onclick="fitParcelBoundary('${escapeHtml(p.id)}')">View parcel boundary</button>`:''}${parcel.gisUrl?`<button class="secondary outline" type="button" onclick="openCountyParcelMap('${escapeHtml(p.id)}')">County GIS ↗</button>`:''}${parcel.recordUrl?`<button class="secondary outline" type="button" onclick="openParcelRecord('${escapeHtml(p.id)}')">Parcel record ↗</button>`:''}</div></div>`;overview.prepend(card);const sourcePanel=document.querySelector('#drawer [data-dossier-tab="Research Sources"]');if(sourcePanel){const detail=document.createElement('div');detail.className='section';detail.innerHTML=`<h3>Parcel & imagery sources</h3><div class="small">County/GIS: ${parcel.source?escapeHtml(parcel.source):'not recorded'}${parcel.checkedAt?` · checked ${escapeHtml(parcel.checkedAt)}`:''}. Parcel geometry: ${normalizeParcelGeometry(p.parcelGeometry)?'verified GeoJSON stored':'not stored'}. Photos: ${photos.primary?'primary image reference saved':'none saved'}.</div>${parcel.notes?`<div class="note">${escapeHtml(parcel.notes)}</div>`:''}`;sourcePanel.appendChild(detail)};document.querySelectorAll('#drawer button').forEach(button=>{if(button.textContent.trim()==='Adjust pin')button.textContent='Adjust property location'})}
function bindDossierImageFallbacks(){document.querySelectorAll('#drawer [data-property-visual] img').forEach(image=>image.addEventListener('error',()=>{const fallback=document.createElement('div');fallback.className='property-photo-placeholder';fallback.textContent='Photo could not be loaded';image.replaceWith(fallback)},{once:true}))}
const openPropertyForDossierTabs=window.openProperty;window.openProperty=function(id){const record=properties.find(item=>item.id===id);window.OTDiagnostics?.setContext?.({propertyId:id,coordinateSource:record?.locationVerification?.source||record?.pinQuality||''});openPropertyForDossierTabs(id);organizeDossier(id);appendDossierPropertySummary(id);bindDossierImageFallbacks()};
window.OTImport={canonicalListingInput,parseListingText,extractTennesseeAddress};
window.OTPropertyMetadata={normalizeParcel,normalizePhotos,normalizeParcelGeometry,locationPriority,isUserConfirmedLocation,canApplyLocation};
